INSERT INTO public.exam_references (id, exam_id, species, gender, min_age_days, max_age_days, reference_text_content, min_value, max_value, unit) VALUES
    ('77777777-7777-4777-8777-777777777701', '33333333-3333-4333-8333-333333333301', 'Canino', 'Ambos', 0, 180, 'Canino Filhote (0 a 6 meses): Eritrócitos: 4,5 - 6,5 milhões/µL | Hemoglobina: 10,0 - 15,0 g/dL | Hematócrito: 30 - 45% | Leucócitos: 7.000 - 18.500 /µL | Plaquetas: 200.000 - 500.000 /µL', 4.50, 6.50, 'milhões/µL'),
    ('77777777-7777-4777-8777-777777777702', '33333333-3333-4333-8333-333333333301', 'Canino', 'Ambos', 181, 36500, 'Canino Adulto (> 6 meses): Eritrócitos: 5,5 - 8,5 milhões/µL | Hemoglobina: 12,0 - 18,0 g/dL | Hematócrito: 37 - 55% | Leucócitos: 6.000 - 17.000 /µL | Plaquetas: 200.000 - 500.000 /µL | PPT: 6,0 - 7,5 g/dL', 5.50, 8.50, 'milhões/µL'),
    ('77777777-7777-4777-8777-777777777703', '33333333-3333-4333-8333-333333333301', 'Felino', 'Ambos', 0, 36500, 'Felino: Eritrócitos: 5,0 - 10,0 milhões/µL | Hemoglobina: 8,0 - 15,0 g/dL | Hematócrito: 24 - 45% | Leucócitos: 5.500 - 19.500 /µL | Plaquetas: 300.000 - 800.000 /µL | PPT: 6,0 - 8,0 g/dL', 5.00, 10.00, 'milhões/µL'),
    ('77777777-7777-4777-8777-777777777704', '33333333-3333-4333-8333-333333333302', 'Canino', 'Ambos', 0, 36500, 'Canino Check Up / Bioquímico: Ureia: 21 - 60 mg/dL | Creatinina: 0,5 - 1,5 mg/dL | ALT (TGP): 10 - 88 U/L | Fosfatase Alcalina: 20 - 156 U/L | Albumina: 2,6 - 3,3 g/dL', 0.50, 1.50, 'mg/dL'),
    ('77777777-7777-4777-8777-777777777705', '33333333-3333-4333-8333-333333333302', 'Felino', 'Ambos', 0, 36500, 'Felino Check Up / Bioquímico: Ureia: 30 - 65 mg/dL | Creatinina: 0,8 - 1,8 mg/dL | ALT (TGP): 20 - 100 U/L | Fosfatase Alcalina: 10 - 90 U/L | Albumina: 2,4 - 3,8 g/dL', 0.80, 1.80, 'mg/dL'),
    ('77777777-7777-4777-8777-777777777706', '33333333-3333-4333-8333-333333333303', 'Felino', 'Ambos', 0, 36500, 'Coproparasitológico Felino/Canino: Ausência de oocistos de protozoários e ovos de helmintos (0 OPG) em amostra fecal fresca.', 0.00, 0.00, 'ovos/g'),
    ('77777777-7777-4777-8777-777777777707', '33333333-3333-4333-8333-333333333304', 'Canino', 'Ambos', 0, 36500, 'Urocultura por Cistocentese: Amostra fisiologicamente estéril (Ausência de crescimento bacteriano). Contagens >= 1.000 UFC/mL em cistocentese são clinicamente significativas.', 0.00, 1000.00, 'UFC/mL'),
    ('77777777-7777-4777-8777-777777777708', '33333333-3333-4333-8333-333333333305', 'Canino', 'Ambos', 180, 36500, 'Canino Adulto Tireoide: T4 Livre: 0,8 - 3,5 ng/dL | TSH Canino: 0,05 - 0,50 ng/mL', 0.80, 3.50, 'ng/dL');
